import type { Config } from '../config/config.js';
import { debugLogger } from '../utils/debugLogger.js';

/**
 * Prefix used to delimit just-in-time discovered project context that is
 * appended to a tool's LLM-facing content.
 */
export const JIT_CONTEXT_PREFIX =
  '\n\n--- Newly Discovered Project Context ---\n';

/**
 * Suffix used to delimit just-in-time discovered project context that is
 * appended to a tool's LLM-facing content.
 */
export const JIT_CONTEXT_SUFFIX = '\n--- End Project Context ---';

/**
 * Discovers just-in-time (JIT) project context for a given accessed path.
 *
 * Traverses upwards from the accessed path (via the active
 * {@link ContextManager}) to discover any project-level context that has not
 * yet been loaded.
 *
 * @param config The active configuration.
 * @param accessedPath The path being accessed by a tool.
 * @returns The newly discovered context, or an empty string if JIT context is
 *   disabled, no context manager is available, nothing is found, or an error
 *   occurs.
 */
export async function discoverJitContext(
  config: Config,
  accessedPath: string,
): Promise<string> {
  if (!config.isJitContextEnabled()) {
    return '';
  }

  const contextManager = config.getContextManager();
  if (!contextManager) {
    return '';
  }

  try {
    const workspaceDirectories = config
      .getWorkspaceContext()
      .getDirectories();
    const discovered = await contextManager.discoverContext(
      accessedPath,
      workspaceDirectories,
    );
    return discovered || '';
  } catch (error) {
    debugLogger.debug(
      `Failed to discover JIT context for '${accessedPath}': ${error}`,
    );
    return '';
  }
}

/**
 * Appends discovered JIT context to the given LLM content.
 *
 * @param llmContent The original LLM-facing content.
 * @param jitContext The discovered JIT context.
 * @returns The original content when `jitContext` is empty, otherwise the
 *   content with the JIT context appended between the configured prefix and
 *   suffix.
 */
export function appendJitContext(
  llmContent: string,
  jitContext: string,
): string {
  if (!jitContext) {
    return llmContent;
  }
  return `${llmContent}${JIT_CONTEXT_PREFIX}${jitContext}${JIT_CONTEXT_SUFFIX}`;
}
